int find(int x) {                 // x가 속한 집합의 루트
    if (p[x] == x) return x;
    return find(p[x]);
}
bool unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return false;     // 이미 같은 집합
    p[b] = a;                     // b의 루트를 a의 루트 밑에
    return true;
}
